#!/usr/bin/env bash
# Prints the upgrade PR description.
# Part 1 is built from the actual changes. Part 2 is a placeholder between the
# markers; the agent's post-script replaces it.
#
# Usage: build-pr-body.sh FROM_REF TARGET_TAG FILES_TSV HARNESS_DIFF
#   FILES_TSV: status, path, additions, deletions (tab-separated) per file.
#   HARNESS_DIFF: `git diff -U0` of .fullsend/harness.
set -euo pipefail
# shellcheck source-path=SCRIPTDIR source=markers.sh
source "$(dirname "${BASH_SOURCE[0]}")/markers.sh"

from_ref="$1" target="$2" files_tsv="$3" harness_diff="$4"

# Files `fullsend repos install` regenerates. Any other file is drift it fixed,
# except the hand-written workflows whose fullsend pins update.sh rewrites.
is_managed() {
  case "$1" in
    .fullsend/config.yaml | .github/workflows/fullsend.yaml | .github/workflows/prioritize.yml | \
      .github/workflows/fullsend-poll-jira.yml) return 0 ;;
    *) return 1 ;;
  esac
}
is_pinned_workflow() {
  case "$1" in
    .github/workflows/fullsend-release-watch.yml | .github/workflows/fullsend-lint.yml) return 0 ;;
    *) return 1 ;;
  esac
}

managed=() other=() pinned=()
while IFS=$'\t' read -r status path adds dels; do
  [[ -n "${path}" ]] || continue
  line="- \`${path}\` (${status}, +${adds} -${dels})"
  if [[ "${path}" == "repos.yaml" || "${path}" == .fullsend/harness/* ]]; then
    continue # shown in the version and pin sections
  elif is_pinned_workflow "${path}"; then
    pinned+=("- \`${path}\`: fullsend action ref → \`${target}\`")
  elif is_managed "${path}"; then
    managed+=("${line}")
  else
    other+=("${line}")
  fi
done < "${files_tsv}"

# Old and new agents-repo commit of each harness `base:` line, and old and new
# digest of each sandbox `image:` line. update.sh pins both to the agents
# release tagged like the target.
pins=$(awk -v tag="${target}" '
  /^\+\+\+ b\// { file = substr($0, 7) }
  /^-base: / { match($0, /agents\/[0-9a-f]{40}/); old = substr($0, RSTART + 7, 12) }
  /^\+base: / { match($0, /agents\/[0-9a-f]{40}/); new = substr($0, RSTART + 7, 12);
                printf "- `%s`: base `%s` → `%s` (fullsend-ai/agents %s)\n", file, old, new, tag }
  /^-image: / { match($0, /sha256:[0-9a-f]{64}/); oldimg = substr($0, RSTART + 7, 12) }
  /^\+image: / { match($0, /sha256:[0-9a-f]{64}/); newimg = substr($0, RSTART + 7, 12);
                 printf "- `%s`: image `%s` → `%s` (fullsend-ai/agents %s)\n", file, oldimg, newimg, tag }
' "${harness_diff}")

print_list() {
  if [[ $# -eq 0 ]]; then echo "_none_"; else printf '%s\n' "$@"; fi
}

cat <<BODY
## 1. What was updated

Upgrades fullsend from \`${from_ref}\` to \`${target}\`, using the \`${target}\` CLI (signature verified).

Sources for part 2: [all changes ${from_ref}...${target}](https://github.com/fullsend-ai/fullsend/compare/${from_ref}...${target}), [release ${target}](https://github.com/fullsend-ai/fullsend/releases/tag/${target}).

### fullsend version
- \`repos.yaml\`: \`github.fullsend_ref\` \`${from_ref}\` → \`${target}\`
$(if [[ ${#pinned[@]} -gt 0 ]]; then printf '%s\n' "${pinned[@]}"; fi)

### Managed files (regenerated by \`fullsend repos install\`)
$(print_list "${managed[@]}")

### Agent harness pins
${pins:-_none_}

### Other changes (drift corrected against the default branch)
$(print_list "${other[@]}")

${ANALYSIS_HEADING}

${ANALYSIS_START}
${ANALYSIS_PLACEHOLDER}
${ANALYSIS_END}
BODY
